    path = pathlib.Path(header.split(': ', 1)[1]); i += 1
    content = path.read_text(); file_lines = content.splitlines(); trailing = content.endswith('\n')
    while i < len(lines) - 1 and not lines[i].startswith('*** '):
        if not lines[i].startswith('@@'): raise SystemExit('expected hunk: ' + lines[i])
