    19	public class PointerFamiliesTest {
    20	  @Test
    21	  public void parsesAndRendersPointers() {
    22	    PointerFamiliesPointers.Pointer pointer = PointerFamiliesPointers.parse("/a~1b/~0/");
    23	
    24	    assertEquals("/a~1b/~0/", PointerFamiliesPointers.render(pointer));
    25	    assertEquals(pointer, PointerFamiliesPointers.parse("/a~1b/~0/"));
    26	    assertEquals("/a~1b/~0/", pointer.toString());
    27	    assertEquals("", PointerFamiliesPointers.render(PointerFamiliesPointers.parse("")));
    28	    assertThrows(PointerFamiliesPointers.MalformedPointerException.class,
    29	        () -> PointerFamiliesPointers.parse("missing-slash"));
    30	    assertThrows(PointerFamiliesPointers.MalformedPointerException.class,
    31	        () -> PointerFamiliesPointers.parse("/bad~2escape"));
    32	  }
