    34	  @Test
    35	  public void resolvesAttributesAndContainers() {
    36	    ImmutablePointerFamilies.Branch root = root();
    37	
    38	    assertSame(root, PointerFamiliesPointers.resolve(root, pointer("")));
    39	    assertEquals("left", PointerFamiliesPointers.resolve(root, pointer("/child/text")));
    40	    assertEquals(2, PointerFamiliesPointers.resolve(root, pointer("/children/1/number")));
    41	    assertEquals("left", PointerFamiliesPointers.resolve(root, pointer("/array/0/text")));
    42	    assertEquals(2, PointerFamiliesPointers.resolve(root, pointer("/named/right/number")));
    43	    assertEquals(2, PointerFamiliesPointers.resolve(root, pointer("/optional/number")));
    44	    assertNull(PointerFamiliesPointers.resolve(root, pointer("/nullable")));
    45	    assertSame(root.children(), PointerFamiliesPointers.resolve(root, pointer("/children")));
    46	
    47	    assertThrows(PointerFamiliesPointers.PointerMissException.class,
    48	        () -> PointerFamiliesPointers.resolve(root, pointer("/missing")));
    49	    assertThrows(PointerFamiliesPointers.PointerMissException.class,
    50	        () -> PointerFamiliesPointers.resolve(root, pointer("/children/9")));
    51	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
    52	        () -> PointerFamiliesPointers.resolve(root, pointer("/children/01")));
    53	    assertThrows(PointerFamiliesPointers.PointerMissException.class,
    54	        () -> PointerFamiliesPointers.resolve(root, pointer("/nullable/text")));
    55	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
    56	        () -> PointerFamiliesPointers.resolve(root, pointer("/set/0")));
    57	  }
