    59	  @Test
    60	  public void updatesOnlyTheAddressedPath() {
    61	    ImmutablePointerFamilies.Branch root = root();
    62	
    63	    ImmutablePointerFamilies.Branch changed = (ImmutablePointerFamilies.Branch)
    64	        PointerFamiliesPointers.update(root, pointer("/child/text"),
    65	            value -> ((String) value).toUpperCase());
    66	
    67	    assertEquals("LEFT", ((PointerFamilies.Text) changed.child()).text());
    68	    assertSame(root.children(), changed.children());
    69	    assertArrayEquals(root.array(), changed.array());
    70	    assertSame(root.named(), changed.named());
    71	    assertSame(root.optional().get(), changed.optional().get());
    72	
    73	    ImmutablePointerFamilies.Branch listChanged = (ImmutablePointerFamilies.Branch)
    74	        PointerFamiliesPointers.update(root, pointer("/children/0/text"), value -> "changed");
    75	    assertEquals("changed", ((PointerFamilies.Text) listChanged.children().get(0)).text());
    76	    assertSame(root.children().get(1), listChanged.children().get(1));
    77	
    78	    ImmutablePointerFamilies.Branch arrayChanged = (ImmutablePointerFamilies.Branch)
    79	        PointerFamiliesPointers.update(root, pointer("/array/1/number"), value -> 3);
    80	    assertEquals(3, ((PointerFamilies.Number) arrayChanged.array()[1]).number());
    81	    assertSame(root.array()[0], arrayChanged.array()[0]);
    82	
    83	    ImmutablePointerFamilies.Branch mapChanged = (ImmutablePointerFamilies.Branch)
    84	        PointerFamiliesPointers.update(root, pointer("/named/left/text"), value -> "map");
    85	    assertEquals(Arrays.asList("left", "right"), new ArrayList<>(mapChanged.named().keySet()));
    86	    assertSame(root.named().get("right"), mapChanged.named().get("right"));
    87	  }
