    89	  @Test
    90	  public void preservesIdentityForEqualResultsAndRejectsBadUpdates() {
    91	    ImmutablePointerFamilies.Branch root = root();
    92	
    93	    assertSame(root, PointerFamiliesPointers.update(root, pointer("/child/text"), value -> value));
    94	    assertSame(root, PointerFamiliesPointers.update(root, pointer(""), value -> root()));
    95	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
    96	        () -> PointerFamiliesPointers.update(root, pointer("/child/text"), value -> 1));
    97	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
    98	        () -> PointerFamiliesPointers.update(root, pointer("/children"), value -> "not a list"));
    99	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
   100	        () -> PointerFamiliesPointers.update(root, pointer(""), value -> "not a root"));
   101	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
   102	        () -> PointerFamiliesPointers.update(root, pointer("/children"),
   103	            value -> Arrays.asList("not a node")));
   104	
   105	    AtomicBoolean called = new AtomicBoolean();
   106	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
   107	        () -> PointerFamiliesPointers.update(root, pointer("/derivedSize"), value -> {
   108	          called.set(true);
   109	          return value;
   110	        }));
   111	    assertFalse(called.get());
   112	
   113	    assertThrows(PointerFamiliesPointers.PointerTypeException.class,
   114	        () -> PointerFamiliesPointers.update(root, pointer("/set"), value -> {
   115	          called.set(true);
   116	          return value;
   117	        }));
   118	    assertFalse(called.get());
   119	  }
