   135	  @Test
   136	  public void handlesWholeContainerReplacement() {
   137	    ImmutablePointerFamilies.Branch root = root();
   138	    List<PointerFamilies.Node> children = Arrays.asList(root.children().get(1));
   139	    Map<String, PointerFamilies.Node> named = new LinkedHashMap<>();
   140	    named.put("only", root.child());
   141	
   142	    ImmutablePointerFamilies.Branch changed = (ImmutablePointerFamilies.Branch)
   143	        PointerFamiliesPointers.update(root, pointer("/children"), value -> children);
   144	    changed = (ImmutablePointerFamilies.Branch)
   145	        PointerFamiliesPointers.update(changed, pointer("/named"), value -> named);
   146	    changed = (ImmutablePointerFamilies.Branch)
   147	        PointerFamiliesPointers.update(changed, pointer("/array"),
   148	            value -> new PointerFamilies.Node[] {root.child()});
   149	
   150	    assertEquals(children, changed.children());
   151	    assertEquals(named, changed.named());
   152	    assertArrayEquals(new PointerFamilies.Node[] {root.child()}, changed.array());
   153	  }
