   155	  private static PointerFamiliesPointers.Pointer pointer(String value) {
   156	    return PointerFamiliesPointers.parse(value);
   157	  }
   158	
   159	  private static ImmutablePointerFamilies.Branch root() {
   160	    ImmutablePointerFamilies.Text left =
   161	        ImmutablePointerFamilies.Text.builder().text("left").build();
   162	    ImmutablePointerFamilies.Number right =
   163	        ImmutablePointerFamilies.Number.builder().number(2).build();
   164	    Map<String, PointerFamilies.Node> named = new LinkedHashMap<>();
   165	    named.put("left", left);
   166	    named.put("right", right);
   167	    return ImmutablePointerFamilies.Branch.builder()
   168	        .child(left)
   169	        .addChildren(left, right)
   170	        .array(left, right)
   171	        .named(named)
   172	        .optional(Optional.of(right))
   173	        .nullable(null)
   174	        .addSet(left)
   175	        .primitiveArray(1, 2)
   176	        .build();
   177	  }
